/* VYRON FIT v24 — Premium home dashboard (HTML builders only; every number is passed in from real app data).
   Zone: level/XP + goal ring, calories, weekly tracker. Strip: weekly schedule cards. Vector art is inline SVG (no image requests). */
import {escapeHTML as E} from "vy/ui";
import {bmr} from "vy/v19-body";
const TX={
 goal:{ar:"تحقيق الهدف",en:"Weekly goal",fr:"Objectif"},
 m0:{ar:"أنت في بداية الطريق.. استمر لتحقيق|هدفك!",en:"You are at the start — keep going to reach|your goal!",fr:"Vous débutez — continuez pour atteindre|votre objectif !"},
 m1:{ar:"تقدّم جيد.. واصل حتى تحقق|هدفك!",en:"Good progress — keep going to reach|your goal!",fr:"Bon progrès — continuez pour atteindre|votre objectif !"},
 m2:{ar:"أنت قريب جداً.. خطوة أخرى نحو|هدفك!",en:"You are very close — one more step to|your goal!",fr:"Vous y êtes presque — encore un pas vers|votre objectif !"},
 m3:{ar:"أحسنت! حققت|هدف الأسبوع!",en:"Well done! You reached|the weekly goal!",fr:"Bravo ! Vous avez atteint|l’objectif de la semaine !"},
 next:{ar:"المستوى القادم",en:"Next level",fr:"Niveau suivant"},
 cal:{ar:"السعرات الحرارية",en:"Calories",fr:"Calories"},
 ofk:{ar:"من {n} سعرة",en:"of {n} kcal",fr:"sur {n} kcal"},
 rem:{ar:"المتبقي لهدفك",en:"Left to goal",fr:"Restant"},
 basal:{ar:"السعرات الأساسية",en:"Basal calories",fr:"Calories de base"},
 act:{ar:"سعرات النشاط",en:"Activity calories",fr:"Calories d'activité"},
 perDay:{ar:"تقدير يومي",en:"daily est.",fr:"est. / jour"},
 noBasal:{ar:"أكمل الوزن والطول والعمر في التغذية",en:"Add weight, height, age in Nutrition",fr:"Ajoutez poids, taille, âge (Nutrition)"},
 lvl:{ar:"المستوى",en:"Level",fr:"Niveau"},
 sess:{ar:"حصص هذا الأسبوع",en:"Sessions this week",fr:"Séances cette semaine"},
 min:{ar:"دقيقة",en:"min",fr:"min"},
 rest:{ar:"راحة",en:"Rest",fr:"Repos"},
 plan:{ar:"تدريب",en:"Workout",fr:"Séance"},
 sch:{ar:"الجدول الأسبوعي",en:"Weekly schedule",fr:"Programme hebdo"},
 today:{ar:"اليوم",en:"Today",fr:"Auj."}};
const T=(k,l,v)=>{let s=(TX[k][l]||TX[k].en);if(v)for(const a in v)s=s.replace("{"+a+"}",v[a]);return s};
const DL={ar:["ح","ن","ث","ر","خ","ج","س"],en:["S","M","T","W","T","F","S"],fr:["D","L","M","M","J","V","S"]};
const len=v=>Math.min(6,String(v).length);
const lg=l=>["ar","en","fr"].includes(l)?l:"en";
/* ---------- vector art ---------- */
const FLAME=`<svg viewBox="0 0 64 72" aria-hidden="true"><defs>
<linearGradient id="flO" x1=".5" y1="0" x2=".5" y2="1"><stop offset="0" stop-color="#ffd24a"/><stop offset=".35" stop-color="#ff9a1f"/><stop offset=".75" stop-color="#ff5a0a"/><stop offset="1" stop-color="#b82300"/></linearGradient>
<linearGradient id="flI" x1=".5" y1="0" x2=".5" y2="1"><stop offset="0" stop-color="#fff6c2"/><stop offset=".5" stop-color="#ffd23a"/><stop offset="1" stop-color="#ff9a1f"/></linearGradient></defs>
<path d="M33 2c3 13-12 19-12 37 0 6 3 11 7 14-5-9 4-14 6-22 6 7 12 12 12 21 0 4-1 7-3 9 10-4 16-12 16-22 0-14-10-22-14-29-2 7-5 9-8 9 1-5 1-11-4-17z" fill="url(#flO)"/>
<path d="M30 70C18 70 10 62 10 51c0-7 4-12 8-17 0 6 3 9 6 11 0-9 4-14 9-20 1 8 9 11 9 22 0 8-6 13-12 13z" transform="translate(11 0) scale(.78) translate(0 14)" fill="url(#flI)"/>
<path d="M33 8c4 6 5 11 3 16-3-3-4-8-3-16z" fill="#fff" opacity=".35"/></svg>`;
const CHECK=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5" fill="none" stroke="currentColor" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const BELL=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.5 6.5v11M3.5 9v6M17.5 6.5v11M20.5 9v6M6.5 12h11" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg>`;
/* ---------- real-data helpers ---------- */
/** Daily basal (BMR) estimate from the Nutrition profile (vyronV21.prof), else the legacy account profile; null when data is missing. */
export function basalKcal(){try{const v=JSON.parse(localStorage.getItem("vyronV21")||"null"),p=v&&v.prof;if(p&&bmr({kg:+p.kg,cm:+p.cm,age:+p.age,sex:p.sex}))return bmr({kg:+p.kg,cm:+p.cm,age:+p.age,sex:p.sex})}catch{}
 try{const g=JSON.parse(localStorage.getItem("vyronProfile")||"null");if(g)return bmr({kg:+g.weight,cm:+g.height,age:+g.age,sex:"x"})}catch{}return null}
const KD="vyronDzDone",KX="vyronDzXp";
function memo(done,xpPct){let fresh=[],from=xpPct;try{const prev=sessionStorage.getItem(KD);if(prev!==null){const s=new Set(prev.split(","));fresh=done.filter(d=>!s.has(d))}
 const f=sessionStorage.getItem(KX);if(f!==null&&+f!==xpPct)from=+f;sessionStorage.setItem(KD,done.join(","));sessionStorage.setItem(KX,String(xpPct))}catch{}return{fresh,from}}
export function homeZone({lang="ar",lvl=1,xpCur=0,xpMax=1000,goalPct=0,kcal=0,kcalGoal=1200,basal=null,done=0,goal=3,minutes=0,days=[],dayNames=[],names={}}){
 const l=lg(lang),n=v=>Math.max(0,Math.round(+v||0)),gp=Math.min(100,n(goalPct)),xp=xpMax>0?Math.min(100,Math.round(xpCur/xpMax*100)):0,
  cp=kcalGoal>0?Math.min(100,Math.round(kcal/kcalGoal*100)):0,msg=gp>=100?"m3":gp>=60?"m2":gp>=25?"m1":"m0",wp=goal>0?Math.min(100,Math.round(done/goal*100)):0,
  M=memo(days.filter(d=>d.done).map(d=>d.date),xp);const [msgA,msgB=""]=T(msg,l).split("|");
 const dots=days.map(d=>{const nm=dayNames[d.i]||"",ch=(DL[l]||DL.en)[d.i]||Array.from(nm)[0]||"",cls=["dz-wd",d.today?"today":"",d.done?"done":"",d.planned&&!d.done?"plan":"",d.st==="rest"&&!d.today?"rest":"",M.fresh.includes(d.date)?"pop":""].filter(Boolean).join(" ");
  return`<span class="${cls}" title="${E(nm)}" aria-label="${E(nm)}${d.done?" ✓":""}"><i>${d.done?CHECK:E(ch)}</i></span>`}).join("");
 return`<section class="dz" aria-label="${E(T("goal",l))}">
 <article class="dz-top dz-plate" dir="${l==="ar"?"rtl":"ltr"}" style="--p:${gp}">
  <img class="dz-bg" src="data:image/webp;base64," alt="" width="1452" height="1083" decoding="async">
  <div class="dz-sh"><b dir="ltr">${n(lvl)}</b><em>${T("lvl",l)}</em></div>
  <div class="dz-xp"><b dir="ltr">${n(xpCur)}<small> / ${n(xpMax)} <u>XP</u></small></b>
   <div class="dz-bar" role="progressbar" aria-label="XP" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${xp}"><i${xp>0?' class="on"':""} data-from="${M.from}" data-to="${xp}" style="width:${xp}%"></i></div></div>
  <div class="dz-nx"><span>${T("next",l)}</span><b dir="ltr">${n(lvl)+1}</b></div>
  <div class="dz-gl"><div class="dz-ring" style="--p:${gp}" role="img" aria-label="${gp}%"><b dir="ltr">${gp}<small>%</small></b></div>
   <div class="dz-gt"><h2>${T("goal",l)}</h2><p>${E(msgA)}${msgB?`<em>${E(msgB)}</em>`:""}</p></div></div></article>
 <div class="dz-row">
 <article class="dz-calp" dir="${l==="ar"?"rtl":"ltr"}" style="--c:${cp}" aria-label="${E(T("cal",l))}">
  <img class="dz-cbg" src="data:image/webp;base64," alt="" width="1535" height="1024" decoding="async">
  <h3 class="dz-ct">${T("cal",l)}</h3>
  <b class="dz-cn" dir="ltr" data-len="${len(n(kcal))}">${n(kcal)}</b>
  <span class="dz-cpill${cp>=100?" ok":""}" dir="ltr">${cp}%${cp>=100?" ✓":""}</span>
  <p class="dz-cof">${T("ofk",l,{n:`<em dir="ltr">${n(kcalGoal)}</em>`})}</p>
  <div class="dz-cbar" role="progressbar" aria-label="${E(T("cal",l))}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${cp}"><i style="width:${cp}%"></i></div>
  <div class="dz-cs a"><h4>${T("rem",l)}</h4><b dir="ltr" data-len="${len(Math.max(0,n(kcalGoal-kcal)))}">${Math.max(0,n(kcalGoal-kcal))}</b></div>
  <div class="dz-cs b"><h4>${T("act",l)}</h4><b dir="ltr" data-len="${len(n(kcal))}">${n(kcal)}</b></div>
  <div class="dz-cs c${basal?" has":""}"><h4>${T("basal",l)}</h4><b dir="ltr" data-len="${basal?len(n(basal)):1}">${basal?n(basal):"—"}</b><small>${basal?T("perDay",l):T("noBasal",l)}</small></div>
 </article>
 <article class="dz-wkp" dir="${l==="ar"?"rtl":"ltr"}" aria-label="${E(T("sess",l))}">
  <img class="dz-wbg" src="data:image/webp;base64," alt="" width="1665" height="944" decoding="async">
  <h3 class="dz-wt" style="font-size:${Math.min(5.8,40/(Array.from(T("sess",l)).length*.52)).toFixed(2)}cqw">${T("sess",l)}</h3>
  <b class="dz-wn" dir="ltr" data-len="${len(String(n(done))+String(n(goal)))}"><span class="g">${n(done)}</span><i>/</i><span>${n(goal)}</span></b>
  <div class="dz-wdays">${dots}</div>
  <div class="dz-wm"><b dir="ltr">${n(minutes)}</b><span>${T("min",l)}</span></div>
 </article></div></section>`}
/** Weekly schedule: seven compact cards; today = emerald gradient, training days accented, rest days dark. */
export function scheduleStrip({lang="ar",days=[],dayNames=[],names={}}){const l=lg(lang);
 return`<section class="dz-sch" aria-label="${E(T("sch",l))}"><div class="dz-sh2"><h2>${T("sch",l)}</h2><button class="link" data-page="schedule" aria-label="${E(T("sch",l))}">›</button></div><div class="dz-sc">${days.map(d=>{const nm=names[d.i],cls=["dz-c",d.today?"today":"",d.done?"done":"",d.planned?"plan":"",d.st==="rest"?"rest":"",d.st==="missed"?"missed":""].filter(Boolean).join(" ");
  return`<button class="${cls}" data-page="schedule"><b>${E(dayNames[d.i]||"")}</b><i>${d.done?CHECK:d.planned?BELL:"·"}</i><span>${E(nm||(d.planned?T("plan",l):T("rest",l)))}</span></button>`}).join("")}</div></section>`}
/** Animate the XP bar from its previous value (this session) and nothing else; respects reduced motion. */
export function animateDz(root){if(matchMedia("(prefers-reduced-motion: reduce)").matches)return;root.querySelectorAll(".dz-bar i[data-from]").forEach(el=>{const f=+el.dataset.from,t=+el.dataset.to;if(f===t)return;el.style.width=f+"%";el.getBoundingClientRect();requestAnimationFrame(()=>{el.style.width=t+"%";el.classList.add("lit");setTimeout(()=>el.classList.remove("lit"),1400)})})}
